36	std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
37	                                    const std::map<std::string, std::string>& ctx,
38	                                    std::string& err) {
39	  std::vector<std::string> out;
40	  out.reserve(tmpl.size());
41	  for (const std::string& arg : tmpl) {
42	    std::string filled;
43	    if (!subst(arg, ctx, filled, err)) return {};
44	    out.push_back(std::move(filled));
45	  }
46	  err.clear();
47	  return out;
48	}
