143	      // step 0 (qemu): drains to state-0.bin; no state_in referenced
144	      check_eq(argvs[0],
145	               {"/qbin", "-object",
146	                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
147	                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
148	                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
149	                "enable=on,target=native", "-bios", "/e", "-plugin",
150	                "/pl,outfile=/wd/state-0.bin"},
151	               "step0");
152	      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
153	      check_eq(argvs[1],
154	               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
155	                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
156	                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
157	               "step1");
158	    }
159	  }
160	  // unknown engine id is an error
161	  {
162	    Plan bad = plan;
163	    bad.steps[0].engine_id = "nope";
164	    std::string err;
165	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
166	    CHECK(!err.empty());
167	  }
168	  // a role the engine has no template for is an error
169	  {
170	    Plan bad = plan;
171	    bad.steps[1].role = "no-such-role";
172	    std::string err;
173	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
174	    CHECK(!err.empty());
175	  }
176	
177	  return andes_sim::test::report("plan");
178	}
