25	struct EngineDescriptor {
26	  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
27	  std::string type;                     // qemu | verilator | alioth | sid
28	  std::string kind;                     // functional | cycle-accurate
29	  long vlen = 0;                        // 0 = not applicable
30	  long xlen = 0;
31	  std::vector<std::string> triggers;    // csr | pc | icount | simpoint
32	  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
33	  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
34	  std::vector<EngineInvoke> invoke;     // argv template per role
35	  std::string result;                   // stderr:<re> | state.mcycle
36	
37	  // Filled by the registry, not present in the JSON:
38	  std::string bin_path;                 // resolved path to the binary
39	  std::string source;                   // built-in | --describe | sidecar
40	
41	  const std::vector<std::string>* invoke_for(std::string_view role) const {
42	    for (const EngineInvoke& iv : invoke)
43	      if (iv.role == role) return &iv.argv;
44	    return nullptr;
45	  }
46	};
