68	// Ask one binary to describe itself: try `<bin> --describe`, else read the
69	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
70	// a human-readable note in `warn`.
71	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
72	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
73	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
74	    json::Parsed p = json::parse(r.out);
75	    if (p.ok) {
76	      std::string err = descriptor_from_json(p.value, d);
77	      if (err.empty()) {
78	        d.bin_path = bin.string();
79	        d.source = "--describe";
80	        return true;
81	      }
82	      warn = bin.string() + ": --describe JSON invalid: " + err;
83	    } else {
84	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
85	    }
86	  }
87	
88	  fs::path sidecar = bin;
89	  sidecar += ".json";
90	  std::error_code ec;
91	  if (fs::exists(sidecar, ec)) {
92	    json::Parsed p = json::parse(read_file(sidecar));
93	    if (p.ok) {
94	      EngineDescriptor sd;
95	      std::string err = descriptor_from_json(p.value, sd);
96	      if (err.empty()) {
97	        sd.bin_path = bin.string();
98	        sd.source = "sidecar";
99	        d = std::move(sd);
100	        return true;
101	      }
102	      warn = sidecar.string() + ": invalid descriptor: " + err;
103	    } else {
104	      warn = sidecar.string() + ": not JSON: " + p.error;
105	    }
106	  }
107	
108	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
109	  return false;
110	}
